using System;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using Petrichor.Core;using Windows.UI.Xaml;using Windows.UI.Xaml.Controls;using Windows.UI.Xaml.Navigation;using Windows.Storage;namespace Petrichor.App.Pages {public sealed partial class SearchPage : MusicPage {public SearchPage(){InitializeComponent();Results=Results0;}
private readonly List<MusicItem> items=new List<MusicItem>();private int generation,offset;private string term="",podcastCursor;private ListView Results;
public int ItemCount=>Results?.Items.Count??0; public string SearchTerm=>term;
protected override async Task LoadAsync(object p){if(p is string){Query.Text=(string)p;await SearchAsync(false);}}
public Task SearchForAsync(string value){Query.Text=value;return ExecuteAsync(()=>SearchAsync(false));}
private async Task SearchAsync(bool next){var q=Query.Text.Trim();if(q.Length==0)return;int revision=++generation,kind=Kind.SelectedIndex,skip=next&&q==term?offset:0;Status.Text="正在搜索…";List<MusicItem> found;bool more;
switch(kind){case 1:var p=await App.Api.SearchPlaylistsAsync(q,30,skip,Token);found=p.Items.Select(MusicItem.From).ToList();more=p.HasMore;break;case 2:var a=await App.Api.SearchArtistsAsync(q,30,skip,Token);found=a.Items.Select(MusicItem.From).ToList();more=a.HasMore;break;case 3:var b=await App.Api.SearchAlbumsAsync(q,30,skip,Token);found=b.Items.Select(MusicItem.From).ToList();more=b.HasMore;break;case 4:var d=await PendingLogic.SearchPodcastsAsync(q,skip==0?null:podcastCursor,Token);found=d.Items;more=d.HasMore;podcastCursor=d.Cursor;break;default:var t=await App.Api.SearchTracksAsync(q,30,skip,Token);found=t.Items.Select(MusicItem.From).ToList();more=t.HasMore;break;}
if(revision!=generation||!IsCurrent)return;if(skip==0)items.Clear();items.AddRange(found);term=q;offset=items.Count;Results.ItemsSource=items.ToList();Status.Text=items.Count==0?(kind==4&&!PendingLogic.PodcastsSupported&&!App.IsDiagnosticsRunning?"播客搜索即将上线。":"没有找到结果，换个关键词试试。"):"找到 "+items.Count+" 个结果";More.Visibility=more?Visibility.Visible:Visibility.Collapsed;}
private async void SubmitClick(object s,RoutedEventArgs e)=>await ExecuteAsync(()=>SearchAsync(false));
private async void MoreClick(object s,RoutedEventArgs e)=>await ExecuteAsync(()=>SearchAsync(true));
private async void QueryKeyDown(object s,Windows.UI.Xaml.Input.KeyRoutedEventArgs e){if(e.Key==Windows.System.VirtualKey.Enter){e.Handled=true;await ExecuteAsync(()=>SearchAsync(false));}}
private async void KindChanged(object s,SelectionChangedEventArgs e){if(Kind!=null&&Results!=null){Results=(ListView)FindName("Results"+Kind.SelectedIndex);if(Frame!=null&&!string.IsNullOrWhiteSpace(Query.Text))await ExecuteAsync(()=>SearchAsync(false));}}
private async void ResultClick(object s,ItemClickEventArgs e){var v=((MusicItem)e.ClickedItem).Value;if(v is PodcastRef)Shell.Current.Navigate(typeof(PodcastPage),v);else if(v is Playlist)Shell.Current.Navigate(typeof(PlaylistPage),v);else if(v is Artist)Shell.Current.Navigate(typeof(ArtistPage),((Artist)v).Id);else if(v is Album)Shell.Current.Navigate(typeof(AlbumPage),((Album)v).Id);else if(v is Track)await ExecuteAsync(()=>PlayTracksAsync(items.Select(x=>x.Value).OfType<Track>().ToList(),(Track)v));}}}
